    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 0.55rem;
      margin: 0 0 1.15rem;
      padding: 0.45rem 0.75rem;
      border: 1px solid rgba(186, 255, 57, 0.28);
      border-radius: 999px;
      color: var(--accent);
      background: rgba(186, 255, 57, 0.08);
      font-size: 0.78rem;
      font-weight: 850;
      letter-spacing: 0.08em;
      text-transform: uppercase;
