      color: var(--muted);
      font-size: clamp(1rem, 2vw, 1.18rem);
    }

    .hero-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.85rem;
      position: relative;
      z-index: 1;
    }

    .button {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      min-height: 48px;
      padding: 0.85rem 1.15rem;
      border: 1px solid transparent;
      border-radius: 999px;
      cursor: pointer;
      font: inherit;
      font-weight: 850;
      transition: transform 180ms ease, border-color 180ms ease, background 180ms ease;
    }

    .button:hover {
      transform: translateY(-2px);
    }

    .button-primary {
      background: var(--accent);
      color: #080a0d;
    }

    .button-secondary {
      border-color: var(--line);
      background: rgba(255, 255, 255, 0.06);
      color: var(--text);
    }

    .hero-card {
      display: grid;
      align-content: end;
      min-height: 540px;
      overflow: hidden;
      border-radius: var(--radius-lg);
      background:
        linear-gradient(180deg, transparent 20%, rgba(9, 11, 16, 0.86) 83%),
        radial-gradient(circle at 50% 24%, rgba(119, 215, 255, 0.32), transparent 13rem),
        linear-gradient(145deg, #202838, #0c1018);
    }

    .product-art {
      display: grid;
      place-items: center;
      min-height: 300px;
      padding: 2rem;
    }

    .shoe {
      width: min(430px, 86%);
      aspect-ratio: 1.55;
      border-radius: 52% 48% 40% 60% / 60% 52% 48% 40%;
      background:
        linear-gradient(145deg, rgba(255, 255, 255, 0.95), rgba(128, 137, 151, 0.92) 48%, rgba(20, 26, 36, 0.96) 49%),
        linear-gradient(90deg, var(--accent), var(--accent-2));
      box-shadow: 0 28px 80px rgba(0, 0, 0, 0.42);
      transform: rotate(-12deg);
      position: relative;
    }

    .shoe::before,
    .shoe::after {
      content: "";
      position: absolute;
      border-radius: 999px;
    }

    .shoe::before {
      inset: 38% 13% 38% 20%;
      background: rgba(7, 9, 13, 0.9);
    }

    .shoe::after {
      right: 9%;
      bottom: -10%;
      width: 30%;
      height: 25%;
      background: var(--accent);
      box-shadow: -150px -22px 0 -19px var(--accent-2);
    }

    .hero-card-content {
