      justify-content: space-between;
      gap: 1rem;
      align-items: end;
      padding: 1.4rem;
    }

    .hero-card h2 {
      font-size: clamp(1.7rem, 4vw, 3rem);
    }

    .hero-card p {
      margin: 0.55rem 0 0;
      color: var(--muted);
    }

    .price-tag {
      flex: 0 0 auto;
      padding: 0.85rem 1rem;
      border-radius: 18px;
      background: var(--text);
      color: #080a0d;
      font-size: 1.2rem;
      font-weight: 950;
    }

    .stats {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 1rem;
      margin: 0 0 32px;
    }

    .stat {
      padding: 1.25rem;
      border: 1px solid var(--line);
      border-radius: var(--radius-md);
      background: rgba(255, 255, 255, 0.05);
    }

    .stat strong {
      display: block;
      font-size: clamp(1.6rem, 4vw, 2.35rem);
      letter-spacing: -0.04em;
    }

    .stat span {
      color: var(--muted);
      font-weight: 700;
    }

    section {
      padding: 42px 0;
    }

    .section-heading {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 1.25rem;
      margin-bottom: 1.25rem;
    }

    .section-heading h2 {
      font-size: clamp(2rem, 5vw, 3.45rem);
    }

    .section-heading p {
      max-width: 44ch;
      margin: 0;
      color: var(--muted);
    }

    .filter-bar {
      display: flex;
      flex-wrap: wrap;
      gap: 0.65rem;
      margin-bottom: 1.25rem;
    }

    .filter-button {
      min-height: 42px;
      padding: 0.65rem 0.95rem;
      border: 1px solid var(--line);
      border-radius: 999px;
      background: rgba(255, 255, 255, 0.05);
      color: var(--muted);
      cursor: pointer;
      font: inherit;
      font-weight: 800;
    }

    .filter-button[aria-pressed="true"] {
      border-color: rgba(186, 255, 57, 0.55);
      background: rgba(186, 255, 57, 0.13);
      color: var(--accent);
    }

    .product-grid {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 1rem;
    }

    .product-card {
      display: flex;
      flex-direction: column;
      min-height: 100%;
      overflow: hidden;
      border-radius: var(--radius-md);
      background: rgba(17, 22, 32, 0.82);
    }

    .product-media {
      min-height: 190px;
      display: grid;
      place-items: center;
      background:
        radial-gradient(circle, rgba(255, 255, 255, 0.18), transparent 5.8rem),
        linear-gradient(145deg, rgba(119, 215, 255, 0.1), rgba(186, 255, 57, 0.08));
    }

    .product-shape {
      width: 118px;
      height: 118px;
      border-radius: 34px;
      background: linear-gradient(145deg, var(--item-color), rgba(255, 255, 255, 0.82));
      box-shadow: 0 18px 42px rgba(0, 0, 0, 0.28);
      transform: rotate(10deg);
    }

    .product-card:nth-child(even) .product-shape {
      border-radius: 50%;
      transform: rotate(-8deg);
    }

    .product-body {
      display: flex;
      flex: 1;
      flex-direction: column;
      gap: 0.8rem;
      padding: 1rem;
    }

    .tag-row {
      display: flex;
      justify-content: space-between;
      gap: 0.75rem;
      color: var(--soft);
      font-size: 0.83rem;
      font-weight: 800;
      text-transform: uppercase;
      letter-spacing: 0.08em;
    }

    .product-card h3,
    .deal-card h3,
    .editorial-card h3 {
      font-size: 1.25rem;
      letter-spacing: -0.035em;
      line-height: 1.1;
    }

    .product-card p,
    .deal-card p,
    .editorial-card p {
      margin: 0;
      color: var(--muted);
    }

    .product-footer {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 0.75rem;
      margin-top: auto;
    }

    .price {
      font-size: 1.22rem;
      font-weight: 950;
    }

    .icon-button {
      display: grid;
      width: 44px;
      height: 44px;
      place-items: center;
      border: 1px solid var(--line);
      border-radius: 50%;
      background: var(--accent);
      color: #080a0d;
      cursor: pointer;
      font: inherit;
      font-weight: 950;
    }

    .deals-grid {
      display: grid;
      grid-template-columns: 1.15fr 0.85fr;
      gap: 1rem;
    }

    .deal-card {
      min-height: 290px;
      padding: clamp(1.25rem, 3vw, 2rem);
      border-radius: var(--radius-lg);
      background:
        linear-gradient(135deg, rgba(255, 255, 255, 0.08), rgba(255, 255, 255, 0.03)),
        radial-gradient(circle at 82% 20%, rgba(255, 189, 89, 0.18), transparent 14rem);
    }

    .deal-card.feature {
      background:
        linear-gradient(135deg, rgba(255, 255, 255, 0.08), rgba(255, 255, 255, 0.03)),
        radial-gradient(circle at 74% 28%, rgba(186, 255, 57, 0.22), transparent 16rem);
    }

    .deal-card h3 {
      max-width: 11ch;
      margin-top: 0.75rem;
      font-size: clamp(2rem, 5vw, 4.25rem);
    }

    .deal-card p {
      max-width: 46ch;
      margin: 1rem 0 1.4rem;
    }

    .countdown {
      display: grid;
      grid-template-columns: repeat(3, minmax(72px, 1fr));
      gap: 0.7rem;
      max-width: 360px;
      margin: 1.3rem 0;
    }

    .time-box {
      padding: 0.9rem;
      border: 1px solid var(--line);
      border-radius: var(--radius-sm);
      background: rgba(0, 0, 0, 0.2);
      text-align: center;
    }

    .time-box strong {
      display: block;
      font-size: 1.55rem;
    }

    .time-box span {
      color: var(--muted);
      font-size: 0.78rem;
      font-weight: 800;
      text-transform: uppercase;
    }

    .editorial-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 1rem;
    }

    .editorial-card {
      overflow: hidden;
      border-radius: var(--radius-md);
      background: rgba(17, 22, 32, 0.82);
    }

    .editorial-image {
      min-height: 210px;
      background:
        linear-gradient(135deg, rgba(255, 255, 255, 0.14), rgba(255, 255, 255, 0)),
        radial-gradient(circle at 30% 30%, var(--story-color), transparent 9rem),
        linear-gradient(145deg, #151b27, #0b0f16);
    }

    .editorial-body {
      padding: 1rem;
    }

    .editorial-body h3 {
      margin: 0.55rem 0;
    }

    .read-link {
      display: inline-flex;
      margin-top: 1rem;
      color: var(--accent);
      font-weight: 900;
    }

    .newsletter {
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 1rem;
      align-items: center;
      margin: 44px 0 56px;
      padding: clamp(1.25rem, 4vw, 2rem);
      border-radius: var(--radius-lg);
      background:
        linear-gradient(135deg, rgba(186, 255, 57, 0.14), rgba(119, 215, 255, 0.08)),
        rgba(17, 22, 32, 0.86);
    }

    .newsletter h2 {
      font-size: clamp(1.8rem, 4vw, 3.1rem);
    }

    .newsletter p {
      margin: 0.75rem 0 0;
      color: var(--muted);
    }

    .newsletter-form {
      display: flex;
      gap: 0.7rem;
      min-width: min(100%, 430px);
    }

    .newsletter-form input {
      width: 100%;
      min-height: 50px;
      border: 1px solid var(--line);
      border-radius: 999px;
      background: rgba(9, 11, 16, 0.76);
      color: var(--text);
      font: inherit;
      padding: 0 1rem;
    }

    .form-status {
      min-height: 1.5rem;
      margin-top: 0.7rem;
      color: var(--accent);
      font-weight: 800;
    }

    footer {
      border-top: 1px solid var(--line);
      padding: 28px 0;
      color: var(--muted);
    }

    .footer-content {
      display: flex;
      justify-content: space-between;
      gap: 1rem;
      align-items: center;
    }

    .footer-links {
      display: flex;
      gap: 1rem;
      font-weight: 800;
    }

    .toast {
      position: fixed;
      right: 1rem;
      bottom: 1rem;
      z-index: 30;
      max-width: min(360px, calc(100% - 2rem));
      padding: 0.9rem 1rem;
      border: 1px solid rgba(186, 255, 57, 0.35);
      border-radius: 16px;
      background: #121925;
      color: var(--text);
      box-shadow: var(--shadow);
      transform: translateY(140%);
      transition: transform 220ms ease;
    }

    .toast.is-visible {
      transform: translateY(0);
    }

    .sr-only {
      position: absolute;
      width: 1px;
      height: 1px;
      padding: 0;
      margin: -1px;
      overflow: hidden;
      clip: rect(0, 0, 0, 0);
      white-space: nowrap;
      border: 0;
    }

    @media (max-width: 980px) {
      .nav {
        flex-wrap: wrap;
        padding: 0.85rem 0;
      }

      .nav-links {
        order: 3;
        width: 100%;
        justify-content: space-between;
      }

      .hero,
      .deals-grid,
      .newsletter {
        grid-template-columns: 1fr;
      }

      .hero-card {
        min-height: 420px;
      }

      .product-grid,
      .editorial-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
      }
    }

    @media (max-width: 680px) {
      .page-shell {
        width: min(100% - 24px, 1180px);
      }

      .nav-links {
        overflow-x: auto;
        justify-content: flex-start;
        padding-bottom: 0.3rem;
      }

      .hero {
        padding-top: 28px;
      }

      .hero-copy {
        padding: 1.35rem;
      }

      .hero-card-content,
      .section-heading,
      .footer-content,
      .product-footer,
      .newsletter-form {
        align-items: stretch;
        flex-direction: column;
      }

      .stats,
      .product-grid,
      .editorial-grid {
        grid-template-columns: 1fr;
      }

      .countdown {
        grid-template-columns: repeat(3, 1fr);
      }

      .newsletter-form {
        display: grid;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      *,
      *::before,
      *::after {
        scroll-behavior: auto !important;
        transition-duration: 0.01ms !important;
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
      }
    }
  </style>
</head>
