  <script>
    const filterButtons = document.querySelectorAll(".filter-button");
    const productCards = document.querySelectorAll(".product-card");
    const cartCount = document.querySelector("#cartCount");
    const cartLink = document.querySelector("#cartLink");
    const toast = document.querySelector("#toast");
    const newsletterForm = document.querySelector("#newsletterForm");
    const formStatus = document.querySelector("#formStatus");
    const countdownTarget = new Date(Date.now() + 2 * 24 * 60 * 60 * 1000 + 18 * 60 * 60 * 1000 + 45 * 60 * 1000);
    let cartItems = 0;
    let toastTimer;

    function showToast(message) {
      toast.textContent = message;
      toast.classList.add("is-visible");
      clearTimeout(toastTimer);
      toastTimer = setTimeout(() => {
        toast.classList.remove("is-visible");
      }, 2600);
    }

    filterButtons.forEach((button) => {
      button.addEventListener("click", () => {
        const filter = button.dataset.filter;

        filterButtons.forEach((item) => {
          item.setAttribute("aria-pressed", String(item === button));
        });

        productCards.forEach((card) => {
          const isVisible = filter === "all" || card.dataset.category === filter;
          card.hidden = !isVisible;
        });
      });
    });

    document.querySelectorAll(".add-to-cart").forEach((button) => {
      button.addEventListener("click", () => {
        cartItems += 1;
        cartCount.textContent = String(cartItems);
        cartLink.setAttribute("aria-label", `Shopping bag with ${cartItems} ${cartItems === 1 ? "item" : "items"}`);
        showToast(`${button.dataset.product} added to your bag.`);
      });
    });

    function updateCountdown() {
      const remaining = Math.max(countdownTarget - Date.now(), 0);
      const totalMinutes = Math.floor(remaining / 60000);
      const days = Math.floor(totalMinutes / 1440);
      const hours = Math.floor((totalMinutes % 1440) / 60);
      const minutes = totalMinutes % 60;

      document.querySelector("#days").textContent = String(days).padStart(2, "0");
      document.querySelector("#hours").textContent = String(hours).padStart(2, "0");
      document.querySelector("#minutes").textContent = String(minutes).padStart(2, "0");
    }

    newsletterForm.addEventListener("submit", (event) => {
      event.preventDefault();
      const email = new FormData(newsletterForm).get("email");
      formStatus.textContent = `Thanks. Deals and editorial drops will be sent to ${email}.`;
      newsletterForm.reset();
    });

    updateCountdown();
    setInterval(updateCountdown, 60000);
  </script>
